/* Evolvlings: path conversations of era 3, El Lago que Recuerda (the ten eras plan, https://claude.ai/artifact/RFy6uGdhz9DJeW7e9ZfdkE).
   Same format as the zone files (see rpg/events-aurora.js). These events only come up while the Glade lives in era 3:
   need.era says so (lore.js needOk), and need.layer counts the guardians beaten since the era began.
   A generation has passed since La Calma: the same Caretaker, older; its creature is the heir. How era 2 ended
   (m2_quinta / m2_linea / m2_ligero) is still in the flags and changes a few lines and options.
   The nine peoples you bring together set the u3_* flags; with all nine, the final dilemma offers the Broken Mirror
   (rpg/data-eras.js derives e3_nueve). The m3_* flags are the marks this era leaves on the next.
   Loaded after the zone files (it adds to them). English text: rpg/events-era3.en.js. */
window.EVEVENTS = window.EVEVENTS || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Entrega 1: el agua que recuerda, el Juicio y las cuatro decisiones ==================== */

  /* ---------- Prado Aurora: la nieta que busca una visión y el Juicio de las Versiones ---------- */
  add("aurora", {
    "e3-candela": { kind: "encuentro", need: { era: 3, layer: 1 }, who: { candela: "Candela Albor" }, start: "a", nodes: {
      a: { say: [[null, "En la fila de testigos de la Plaza del Juicio, una muchacha con un abrigo bueno y gastado cuenta monedas en la palma de la mano. Delante de ella, un aguador de las Mareas vende copas de agua oscura."],
                 ["candela", "Tres copas más y tengo la noche entera. La Velada Negra, desde la Torre del Alba. Quiero ver la cara de mi abuela cuando se encendieron los faroles."],
                 ["candela", "Dicen que ella sabía lo de la savia y no dijo nada. Yo quiero probar que no sabía. Me llamo Candela. Candela Albor, aunque ese apellido ya no le abre la puerta a nadie."]],
           opts: [{ t: "«¿Y si la visión dice que sabía?»", go: "sabia", once: true },
                  { t: "«Yo estuve esa noche en la plaza. Te cuento lo que vi.»", go: "contar" },
                  { t: "Pagarle las tres copas", go: "pagar", fx: { cost: 30 } },
                  { t: "«Tu abuela tenía un cuaderno. ¿Lo buscaste?»", go: "cuaderno", cNeed: "e2_aureliaGuarda" },
                  { t: "«No bebas. Esa agua le quita algo a la Raíz.»", go: "nobeber" }] },
      sabia: { say: [["candela", "Entonces la visión miente. O la vendieron cortada. En los Altos cortan las noches como pan."],
                     [null, "Lo dice muy rápido. Se nota que lo tiene pensado desde hace mucho."]], back: "a" },
      contar: { say: [[null, "Le cuentas la Velada: la plaza blanca de luz, la savia negra subiendo por las juntas, la matriarca nueva en el balcón. No sabes qué vio la abuela. Ella no estaba en la plaza."],
                      ["candela", "¿No fue? ¿Mi abuela no fue a la Velada?"],
                      ["candela", "Entonces sí sabía algo. Una no se queda en casa la noche más larga del año porque sí."],
                      [null, "Guarda las monedas. No parece aliviada. Parece que le hubieran quitado el suelo."]], end: { xp: 12, flag: "e3_candelaSabe" } },
      pagar: { say: [[null, "Le pagas las copas. Candela bebe las tres seguidas, con los ojos cerrados. Tarda en volver."],
                     ["candela", "La vi. En su casa, sola, con un cuaderno en las rodillas. No lo abría. Lo tenía apretado, como se aprieta una herida."],
                     ["candela", "No se ve qué decía el cuaderno. Las visiones no leen. Solo sienten. Y ella sentía miedo, no culpa. ¿Eso prueba algo?"]], end: { xp: 14, flag: ["e3_candelaBebe", "e3_visionAurelia"] } },
      cuaderno: { say: [["candela", "¿Un cuaderno? ¿Usted sabe de un cuaderno?"],
                        [null, "Le cuentas que Aurelia no quiso quemarlo. Que dijo que, si alguien lo necesitaba, sabría dónde estaba: dándole órdenes a un geranio."],
                        ["candela", "El geranio. Sigue en la ventana. Nadie lo toca porque era de ella."],
                        [null, "Vuelve al día siguiente con el cuaderno de hule envuelto en un pañuelo. Lo ha leído entero. Tiene los ojos hinchados."],
                        ["candela", "Sabía. Y lo escribió todo para que alguien lo supiera después. Eso no la salva. Pero las Casas del Farol van a declarar con esto en la mano, y no con agua comprada."]], end: { xp: 20, flag: ["e3_cuadernoAlbor", "u3_luz"], escrito: "e3-cuaderno-hule" } },
      nobeber: { say: [["candela", "¿Le quita algo? Todo el mundo bebe. Los jueces beben. Si no bebo, declaro con las manos vacías."],
                       [null, "Pero se sale de la fila. Se queda mirando las copas desde lejos, con las monedas apretadas."]], end: { xp: 8, flag: "e3_candelaNoBebe" } },
    } },

    "e3-juicio": { kind: "dialogo", need: { era: 3, layer: 2 }, who: { albura: "Jueza Albura" }, start: "a", nodes: {
      a: { say: [[null, "La Plaza del Juicio está llena hasta los tejados. En la tarima, una jueza de la Luz con la toga blanca escucha a los testigos uno por uno. Cada uno trae una copa vacía, la prueba de que bebió."],
                 ["albura", "Las Casas dicen que la Velada Negra la provocaron las sombras de la Corte, que cavaron bajo la plaza. La Corte dice que la provocaron los faroles de las Casas, que bebieron demasiado."],
                 ["albura", "Las dos versiones tienen visiones que las prueban. Las dos son verdad a medias. Usted estuvo ahí, Cuidador. Su palabra pesa más que cualquier copa. ¿A favor de quién declara?"]],
           opts: [{ t: "«¿Qué pasa con el pueblo que pierda?»", go: "pierde", once: true },
                  { t: "«Bebieron todos. ¿Por qué tiene que haber un culpable?»", go: "todos", once: true },
                  { t: "Declarar a favor de las Casas: la culpa es de la Corte", go: "casas" },
                  { t: "Declarar a favor de la Corte: la culpa es de las Casas", go: "corte" },
                  { t: "No declarar a favor de nadie", go: "nadie" }] },
      pierde: { say: [["albura", "Paga. Reparaciones, tierras, nombres. Así funcionan los juicios. Alguien tiene que pagar para que los demás puedan dormir."],
                      ["albura", "No me mire así. No inventé la justicia. Solo la administro."]], back: "a" },
      todos: { say: [["albura", "Porque un juicio sin culpable no cierra nada. La gente vuelve a casa con la herida abierta y la rabia sin dueño."],
                     ["albura", "Una herida cerrada en falso también duele, ya lo sé. Pero duele más despacio."]], back: "a" },
      casas: { say: [[null, "Declaras. Cuentas la savia negra en las juntas, la Corte que cavaba sus pasajes debajo, las sombras que nadie paró."],
                     [null, "No mientes. Solo cuentas la mitad. Las Casas aplauden. Desde el fondo de la plaza, los de la Corte se bajan el velo, todos a la vez, como una sola cara."],
                     ["albura", "Queda escrito. La Corte cargará con esto durante generaciones. Espero que tenga razón, Cuidador."]], end: { xp: 16, flag: "m3_culpaCorte" } },
      corte: { say: [[null, "Declaras. Cuentas la plaza blanca de luz, los pozos que la matriarca abrió, los faroles que bebían más de lo que la Raíz podía dar."],
                     [null, "No mientes. Solo cuentas la mitad. La Corte se quita el velo por primera vez en el juicio. Las Casas te miran como se mira a un traidor."],
                     ["albura", "Queda escrito. Las Casas pagarán. Y alguien comprará barato lo que vendan para pagar. Siempre hay alguien."]], end: { xp: 16, flag: "m3_culpaCasas" } },
      nadie: { say: [["albura", "¿A favor de nadie? Entonces su palabra no vale nada en este juicio."],
                     [null, "Pero la plaza se queda callada. Un viejo de la Corte, en la primera fila, asiente despacio. Una mujer de las Casas, a su lado, también."],
                     ["albura", "Lo anoto. «El Cuidador dice que bebieron todos.» Nadie va a pagar por eso. Y nadie va a sanar por eso tampoco."]], end: { xp: 18, flag: "m3_culpaNadie" } },
    } },
  });

  /* ---------- Cráter Tibio: las copas de cristal ---------- */
  add("crater", {
    "e3-copas": { kind: "dialogo", need: { era: 3, layer: 1 }, who: { fogarin: "Fogarín" }, start: "a", nodes: {
      a: { say: [[null, "El taller más grande del Cráter ya no hace tubos. Hace copas. Cientos, de cristal grueso, con tapa de cera y un sello del Gremio. Dentro de cada una, agua oscura que se mueve sola."],
                 [null, "El maestro del taller tiene canas en la barba y las manos llenas de cicatrices de vidrio. Lo reconoces por los ojos: el aprendiz del fuelle, una generación después."],
                 ["fogarin", "Cuidador. Pensé que ya no te vería. Mira esto. Una visión cerrada se vende diez veces más que una bebida. Las Casas compran, la Corte compra, todos compran."]],
           opts: [{ t: "«¿De dónde sale el agua?»", go: "agua", once: true },
                  { t: "Mirar una copa a contraluz", go: "mirar", once: true },
                  { t: "«Con lo que ganan, el Fuego podría dejar de vender.»", go: "dejar" },
                  { t: "Pedirle que haga tubos otra vez, para medir lo que la Raíz pierde", go: "tubos", cNeed: "e2_tuboAfinado" },
                  { t: "«Esto es lo mismo que los tubos largos.»", go: "mismo" }] },
      agua: { say: [["fogarin", "Del lago. Las Mareas la sacan de abajo, muy abajo, con cubos atados a cuerdas larguísimas. Nos la venden por barriles."],
                    ["fogarin", "Ola dice que no saca más de lo que el lago repone. No sé cómo lo sabe. Pero le creo. A ella le creo todo."]], back: "a" },
      mirar: { say: [[null, "Levantas una copa hacia la luz del horno. Dentro, pequeñita, una plaza blanca de faroles. La gente baila. Y abajo, en las juntas, algo negro sube despacio."],
                     ["fogarin", "Esa es de la Velada. Las de la Velada se venden primero. Todos quieren ver de quién fue la culpa."]], back: "a" },
      dejar: { say: [["fogarin", "¿Dejar de vender? El Fuego siempre vendió. Vendimos tubos, después carbón, ahora copas. Pero esta vez, por primera vez, ponemos nosotros el precio."],
                     [null, "Se queda mirando el horno."],
                     ["fogarin", "Está bien. Le voy a proponer algo al Gremio: una copa de cada diez no se vende. Se guarda. Si algún día hay que devolver lo que sacamos, que haya algo para devolver."]], end: { xp: 16, flag: ["e3_copaGuardada", "u3_fuego"] } },
      tubos: { say: [[null, "Fogarín se ríe. Una risa de antes, de aprendiz."],
                     ["fogarin", "¿Los tubos que cantan? Los tengo en la pared, llenos de polvo."],
                     [null, "Baja uno y lo apunta hacia el lago. La nota no sale ronca. Sale vacía, como si soplaras en una casa abandonada."],
                     ["fogarin", "No está enferma. Está... olvidando. El vidrio canta así cuando le falta algo adentro. Voy a hacer más. Que todo el Gremio oiga esto antes de vender una copa más."]], end: { xp: 20, flag: ["e3_tuboVacio", "u3_fuego"] } },
      mismo: { say: [["fogarin", "No es lo mismo. Los tubos bebían de la Raíz. Esto es agua."],
                     [null, "Pero no te mira cuando lo dice. Sigue soplando el vidrio, más rápido que antes."]], end: { xp: 6 } },
    } },

    "e3-ampolla": { kind: "encuentro", need: { era: 3, layer: 1 }, who: { ampolla: "Ampolla, sopladora" }, start: "a", nodes: {
      a: { say: [[null, "Detrás del taller, una sopladora de vidrio con la cara roja de calor está rompiendo copas a martillazos. Una por una. El agua oscura se escurre entre las piedras y desaparece."],
                 ["ampolla", "No me mires así. Son las mías. Las que soplé yo. Las vendí y me las devolvieron."],
                 ["ampolla", "Dicen que están falladas. Que las visiones de mis copas se ven distintas cada vez que las miras. Una mañana la Velada tiene un final, a la tarde tiene otro."]],
           opts: [{ t: "«¿Distintas cómo?»", go: "como", once: true },
                  { t: "Guardar una copa antes de que la rompa", go: "guardar" },
                  { t: "Ayudarla a romperlas", go: "romper" },
                  { t: "«Llévalas a las Cuevas. Allá graban lo que se ve.»", go: "cuevas" }] },
      como: { say: [["ampolla", "En una, la matriarca ve el suelo negro y no hace nada. En la misma copa, al día siguiente, la matriarca no ve nada. Como si la visión se acordara distinto cada vez."],
                    ["ampolla", "El Gremio dice que es mi vidrio, que está mal templado. Yo digo que no es el vidrio. Es lo de adentro. Se está olvidando de sí mismo."]], back: "a" },
      guardar: { say: [[null, "Le quitas una copa de la mano antes del martillazo. Ampolla no protesta."],
                       ["ampolla", "Llévatela. Mírala cada semana. Si cambia, ya sabes lo que pasa con lo que sacamos del fondo: ni el agua se acuerda bien de lo que vio."]], end: { xp: 12, flag: "e3_copaCambia" } },
      romper: { say: [[null, "Rompen las copas entre las dos personas hasta que no queda ninguna. El suelo se oscurece un momento y vuelve a secarse."],
                      ["ampolla", "Ya está. Que el Gremio me descuente lo que quiera. Por lo menos estas no van a declarar en ningún juicio."]], end: { xp: 8, flag: "e3_copasRotas" } },
      cuevas: { say: [["ampolla", "¿A los de la piedra? Ellos graban todo. Si una visión cambia, la piedra va a tener dos versiones."],
                      [null, "Lo piensa. Guarda el martillo."],
                      ["ampolla", "A lo mejor eso es lo que hay que mostrar en el juicio. No una noche. Dos noches que no coinciden."]], end: { xp: 14, flag: "e3_copasCuevas" } },
    } },
  });

  /* ---------- Bosque Hondo: el agua prohibida ---------- */
  add("forest", {
    "e3-llovizna": { kind: "dialogo", need: { era: 3, layer: 1 }, who: { llovizna: "Llovizna" }, start: "a", nodes: {
      a: { say: [[null, "En la entrada del Bosque hay un cartel nuevo, tallado en madera: «Prohibido traer agua del lago. Por orden del Concejo». Al lado, una mujer con una cuchara de madera colgada del cuello lo vigila."],
                 [null, "La niña de la mochila es ahora concejala. Tiene arrugas alrededor de los ojos y la misma voz de pájaro."],
                 ["llovizna", "Cuidador. El abuelo Liquen decía que volverías cuando las cosas se pusieran feas. Se murió hace seis inviernos. Ya no se acordaba de su nombre, pero se acordaba del tuyo."]],
           opts: [{ t: "«¿Por qué lo prohibieron?»", go: "porque", once: true },
                  { t: "«Siento lo del abuelo.»", go: "abuelo", once: true },
                  { t: "«Si lo prohiben, los jóvenes van a ir igual, de noche.»", go: "jovenes" },
                  { t: "Cantar con ella la canción del Bosque", go: "cantar", cNeed: "e2_lloviznaCanta" },
                  { t: "«Tienen razón. Mantengan la prohibición.»", go: "razon" }] },
      porque: { say: [["llovizna", "Porque el Bosque olvida. Es lo único que sabemos hacer bien: el Largo Silencio, el olvido que cura. Y esa agua es lo contrario. Te obliga a acordarte de lo que no viviste."],
                      ["llovizna", "Los que la beben vuelven raros. Se acuerdan de la Velada como si hubieran estado. Lloran por gente que no conocieron."]], back: "a" },
      abuelo: { say: [["llovizna", "Yo le escribía en hojas secas lo que se le iba olvidando. Al final había más hojas que abuelo."],
                      ["llovizna", "Las guardo en una caja. A veces pienso que eso es lo mismo que hacen las Mareas con el agua. Después me da vergüenza pensarlo."]], back: "a" },
      jovenes: { say: [["llovizna", "Ya van. Diecinueve este mes. Tres no volvieron. Se quedaron en la orilla, bebiendo, viendo noches ajenas."],
                       [null, "Se quita la cuchara del cuello y la mira."],
                       ["llovizna", "Bueno. Quitemos el cartel. Pero alguien del Concejo va a ir con ellos al lago, a cuidarlos mientras beben. Si no se lo podemos prohibir, por lo menos que no estén solos."]], end: { xp: 16, flag: ["e3_bosqueAcompana", "u3_planta"] } },
      cantar: { say: [[null, "Cantan la canción del Bosque, la que no da luz. Llovizna canta desafinada, como siempre. Los guardias del cartel dejan de vigilar para escuchar."],
                      ["llovizna", "Esta canción es para olvidar despacio, sin que duela. Mira: hasta tu criatura se quedó tranquila."],
                      ["llovizna", "Si algún día el Corazón pide que los pueblos vayan, el Bosque va a ir. No a declarar. A cantar esto, para que alguien olvide sin miedo."]], end: { xp: 18, heal: 0.2, flag: ["e3_cancionOlvido", "u3_planta"] } },
      razon: { say: [["llovizna", "Tenemos razón. Ya lo sé. Tener razón nunca alcanzó para que nadie se quedara."],
                     [null, "Vuelve a colgarse la cuchara. Esa noche, el cartel amanece con una frase más, tallada con cuchillo: «Ustedes ya olvidaron todo. Nosotros queremos saber»."]], end: { xp: 6, flag: "e3_bosqueProhibe" } },
    } },

    "e3-retono": { kind: "encuentro", need: { era: 3, layer: 2 }, who: { retono: "Retoño" }, start: "a", nodes: {
      a: { say: [[null, "En un claro del Bosque, un muchacho flaco llena una cantimplora con agua oscura de un barril escondido entre helechos. Tiene la boca morada y los ojos muy abiertos."],
                 ["retono", "¿Vienes a llevarme al Concejo? Llévame. Ya vi lo que quería ver."],
                 ["retono", "Vi a mi bisabuela. Cuando llegó al Bosque como desplazada, con una bellota en la mano. Nadie me lo había contado. En el Bosque nadie cuenta nada. Todo se olvida."]],
           opts: [{ t: "«¿Qué más viste?»", go: "mas", once: true },
                  { t: "Quitarle la cantimplora", go: "quitar" },
                  { t: "«Cuéntaselo al Concejo. Que lo escuchen.»", go: "concejo" },
                  { t: "Beber con él", go: "beber" }] },
      mas: { say: [["retono", "Que el Seto se cerró después de que ella entró. Que el Bosque que nos enseñan a querer se hizo cerrándole la puerta a gente como ella."],
                   ["retono", "Mi abuela me pegaba si preguntaba de dónde veníamos. Ahora sé por qué. No por vergüenza. Por miedo a que alguien nos echara."]], back: "a" },
      quitar: { say: [[null, "Le quitas la cantimplora. No se resiste. Se sienta en el suelo con las manos en las rodillas."],
                      ["retono", "Ya está adentro. Lo que vi no me lo puedes quitar. Solo me quitas lo que no vi todavía."]], end: { xp: 8, flag: "e3_retonoSin" } },
      concejo: { say: [[null, "Lo acompañas al Concejo. Retoño cuenta lo que vio. Los viejos se quedan callados. Llovizna, al fondo, aprieta la cuchara."],
                       [null, "Nadie lo castiga. Pero esa noche, en tres casas del Bosque, alguien le pregunta a su abuela de dónde vinieron. Y la abuela contesta."]], end: { xp: 16, flag: "e3_bosquePregunta" } },
      beber: { say: [[null, "Bebes de su cantimplora. El agua sabe a tierra y a hierro. Ves una noche de lluvia en el Seto: un guarda joven deja pasar a una niña con una bellota, y luego cierra con llave."],
                     [null, "El guarda tiene la cara del Abuelo Liquen, joven. No sabes si eso es lo que pasó o lo que la Raíz sintió que pasaba."],
                     ["retono", "¿Ves? No hay culpables. Solo gente asustada cerrando puertas. Así no se gana ningún juicio."]], end: { xp: 14, hurt: 0.08, flag: "e3_bebisteSeto" } },
    } },
  });

  /* ---------- Los Altos: visiones cortadas ---------- */
  add("heights", {
    "e3-trueque": { kind: "encuentro", need: { era: 3, layer: 1 }, who: { trueque: "Trueque, mercader" }, start: "a", nodes: {
      a: { say: [[null, "En el mirador del viento ya no hay cometas. Hay un puesto con un toldo a rayas y cientos de frasquitos colgados de hilos, cada uno con un poco de agua oscura y una etiqueta."],
                 ["trueque", "¡Pasen, pasen! El principio de la Velada, barato. El final, más caro. La cara de la matriarca, carísima. Se vende por pedazos, como todo lo bueno."],
                 ["trueque", "Los Altos siempre vendieron versos. Ahora vendemos pedazos de noches. Es lo mismo: nadie quiere la historia entera, quiere la parte que le da la razón."]],
           opts: [{ t: "«¿Quién corta las visiones?»", go: "quien", once: true },
                  { t: "Comprar el final de la Velada", go: "comprar", fx: { cost: 25 } },
                  { t: "«Vender pedazos es mentir.»", go: "mentir" },
                  { t: "«Vendan la noche entera, sin cortar. Aunque nadie la compre.»", go: "entera" }] },
      quien: { say: [["trueque", "Una vieja que vive en el archivo del Trueno. Dice que antes escribía registros. Corta las visiones con una pluma de cuervo y una copa de leche. No pregunten cómo."],
                     ["trueque", "Glosa, se llama. Dice que es lo mismo que hacía antes: elegir qué se guarda y qué no."]], back: "a" },
      comprar: { say: [[null, "Bebes el frasquito. Ves el final de la Velada: la plaza vacía, los faroles todavía encendidos, y en el balcón, sola, la matriarca nueva mirando el suelo negro con las manos en la cara."],
                       [null, "No sabes qué pasó antes. Ni después. Solo ese momento, y lo que la Raíz sintió: algo parecido a la lástima."]], end: { xp: 12, flag: "e3_finalVelada" } },
      mentir: { say: [["trueque", "¿Mentir? Todo lo que vendo es verdad. Cortado, pero verdad."],
                      ["trueque", "Lo que miente es la gente que compra la mitad y la cuenta como si fuera el todo. Yo solo vendo pan. Ellos lo convierten en piedras."]], end: { xp: 6 } },
      entera: { say: [["trueque", "¿Entera? Una noche entera no le sirve a nadie. Tiene culpables por todos lados."],
                      [null, "Pero baja un frasco grande del fondo del puesto, uno que no tiene etiqueta."],
                      ["trueque", "Está bien. Una. Sin cortar. Que la vea quien quiera, gratis, aquí en el mirador. Los Altos siempre fueron los que llevaban mensajes enteros. Hace mucho que no."],
                      [null, "Al día siguiente hay fila. Corta, pero hay. Y cuando el Corazón llame, dice Trueque, los Altos llevarán el frasco grande."]], end: { xp: 18, flag: ["e3_nocheEntera", "u3_altos"] } },
    } },

    "e3-glosa": { kind: "dialogo", need: { era: 3, layer: 2 }, who: { glosa: "Glosa, archivera del Trueno" }, start: "a", nodes: {
      a: { say: [[null, "En el archivo del Trueno, una anciana muy encorvada tiene una copa de leche delante y una pluma de cuervo en la mano. Mete la punta en el agua oscura y la saca con un hilo de recuerdo pegado, como se saca una hebra de un ovillo."],
                 ["glosa", "Tú. Te acuerdo. Me ayudaste a escribir un registro, una vez. No me acuerdo si el falso o el verdadero."],
                 ["glosa", "Ahora corto visiones. Es el mismo oficio: decidir qué parte de una noche se queda en el papel. Antes lo hacía con tinta. Ahora con una pluma mojada."]],
           opts: [{ t: "«¿Qué hace con los pedazos que nadie compra?»", go: "sobras", once: true },
                  { t: "«Usted escribió el registro falso de la tormenta.»", go: "falso", cNeed: "e2_registroFalso" },
                  { t: "«Usted guardó la verdad del cielo limpio.»", go: "verdad", cNeed: "e2_registroCefira" },
                  { t: "Pedirle que deje de cortar", go: "dejar" }] },
      sobras: { say: [["glosa", "Los tiro al viento. El viento baja al Corazón. Supongo que ahí abajo se juntan todas las partes de las noches que nadie quiso."],
                      ["glosa", "A lo mejor la Raíz se está tragando lo que nosotros no queremos recordar. Sería justo."]], back: "a" },
      falso: { say: [["glosa", "El falso. Sí. Ya me acuerdo. Lo usaron para volver a comprar a los Altos. Funcionó tres inviernos. Después alguien bebió una visión del cielo de esa semana y vio que estaba limpio."],
                     ["glosa", "Desde entonces nadie cree en ningún papel de los Altos. Por eso vendemos agua. El agua no se puede falsificar. Solo se puede cortar."]], back: "a" },
      verdad: { say: [["glosa", "El verdadero. Sí. La Dama lo leyó en voz alta, al final, en la plaza del Prado. Se le quebró la voz en la parte de los vientos."],
                      ["glosa", "Ese papel lo guardo todavía. No lo vendo. Es lo único que escribí que no tuve que cortar."]], back: "a" },
      dejar: { say: [[null, "Glosa deja la pluma sobre la mesa. Tarda en contestar."],
                     ["glosa", "Si dejo de cortar, otros cortan peor. Yo por lo menos dejo las caras enteras."],
                     ["glosa", "Pero te voy a dar algo. Los pedazos que corté de la Velada, todos, en el orden en que los corté. Para que alguien vea qué partes se vendieron más. Eso también es una historia."]], end: { xp: 16, flag: "e3_listaCortes", escrito: "e3-cortes-glosa" } },
    } },
  });

  /* ---------- Hondonada Umbría: la muerte de Noctua y el Barrio que se acuerda ---------- */
  add("hollow", {
    "e3-noctua": { kind: "dialogo", need: { era: 3, layer: 1 }, who: { umbela: "Umbela, archivera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En la casa de Noctua, la sanadora del primer brote, las flores secas de la puerta llegan al techo. Adentro, una mujer con velo ordena copas vacías en filas sobre la mesa. Hay cuarenta."],
                 ["umbela", "Cuarenta visiones de esta casa. Ninguna muestra cómo murió. La Raíz no estaba mirando, o no quiso mirar."],
                 ["umbela", "Si encuentro esa visión, la Corte queda libre. Las Casas dicen que Noctua murió porque la Corte le dio savia para curar. Nosotros decimos que murió curando a gente de las Casas que nadie más quiso tocar."]],
           opts: [{ t: "«¿Y si murió por las dos cosas?»", go: "dos", once: true },
                  { t: "Buscar en la casa en vez de en el agua", go: "casa" },
                  { t: "«En esta casa había una nota: el rey no preguntó.»", go: "nota", cNeed: "notaNoctua" },
                  { t: "«Deje de buscar. Esa muerte no la va a salvar.»", go: "dejar" }] },
      dos: { say: [["umbela", "Entonces la Corte es culpable a medias, y en un juicio la mitad de la culpa pesa lo mismo que la entera."],
                   ["umbela", "Por eso busco. No la verdad. Una verdad que pese menos."]], back: "a" },
      casa: { say: [[null, "Buscas en los cajones, bajo las tablas, detrás de las flores. En el fondo de un frasco vacío hay un papel enrollado, de letra temblorosa."],
                    [null, "Es una lista: los nombres de los enfermos que Noctua curó en el primer brote. La mitad son de las Casas. La otra mitad, de la Corte. Al final, con otra tinta: «Ninguno preguntó de dónde salía el remedio»."],
                    ["umbela", "Nadie preguntó. Ni ellos ni nosotros. Esto no salva a la Corte. Pero tampoco la condena sola."],
                    [null, "Guarda el papel bajo el velo. Esa noche, la Corte decide declarar con la lista en vez de con el agua. Y te pide que estés con ella cuando el Corazón llame."]], end: { xp: 20, flag: ["e3_listaNoctua", "u3_sombra"] } },
      nota: { say: [["umbela", "¿El rey no preguntó? ¿Cuál rey? ¿El nuestro?"],
                    [null, "Le cuentas dónde estaba la nota. Umbela se sienta despacio, entre las copas vacías."],
                    ["umbela", "Entonces el rey sabía de dónde salía la savia y no preguntó para no tener que saberlo. Eso es peor que cualquier visión."],
                    ["umbela", "Voy a declarar esto. Contra mi propia Corte. Si no lo digo yo, lo va a decir un juez de la Luz, y lo va a decir peor."]], end: { xp: 18, flag: ["e3_reyNoPregunto", "u3_sombra"] } },
      dejar: { say: [["umbela", "No me va a salvar. Lo sé. Pero buscar es lo único que la Corte me dejó hacer."],
                     [null, "Vuelve a ordenar las copas. Cuarenta y una. Alguien trajo otra mientras hablaban."]], end: { xp: 6 } },
    } },

    "e3-nim": { kind: "dialogo", need: { era: 3, layer: 2 }, who: { nim: "Nim" }, start: "a", nodes: {
      a: { say: [[null, "En la puerta del Barrio Apagado, un hombre de unos treinta años canta solo, bajito, con las manos en los bolsillos. Lo reconoces por la nana. Es Nim, una generación después."],
                 ["nim", "Cuidador. Te pasaron los años encima. A mí también, no te creas."],
                 ["nim", "Todos quieren ver la Velada. Nadie quiere ver lo que pasó en el Barrio después. Las noches sin luz, los que se fueron, los que volvieron. Eso no está en ninguna copa porque nadie paga por verlo."]],
           opts: [{ t: "«¿Qué pasó en el Barrio después?»", go: "despues", once: true },
                  { t: "«Tú te viniste conmigo, aquella noche del coro.»", go: "coro", cNeed: "e2_nimLejos" },
                  { t: "«Tú te quedaste al lado. Y tu madre vino.»", go: "madre", cNeed: "e2_nimQueda" },
                  { t: "«Cántalo en el Juicio. Lo que nadie compra.»", go: "juicio" },
                  { t: "Escucharlo cantar", go: "escuchar" }] },
      despues: { say: [["nim", "Depende de cómo terminó tu Calma. Pero siempre lo mismo: el Barrio paga. Con luz o sin luz, el Barrio paga."],
                       ["nim", "Ahora vienen las Casas y la Corte a pelearse por quién tuvo la culpa. Y en medio está el Barrio, que no tiene copa, ni Casa, ni velo."]], back: "a" },
      coro: { say: [["nim", "Me acuerdo. Canté la nana entera en esta puerta y no brilló ningún farol. Esa fue la primera vez que canté para mí."],
                    ["nim", "Desde entonces la canto aquí una vez al año. Gratis. La gente del Barrio viene. No es mucho. Pero es nuestro."]], back: "a" },
      madre: { say: [["nim", "Vino. Enojada, cada semana, durante tres años. Al cuarto año se quedó a vivir conmigo."],
                     ["nim", "Murió el invierno pasado. Antes de morirse me dijo que el que decidió no fuiste tú, ni yo, ni Tila. Que fueron los tres. Supongo que eso es perdonar."]], back: "a" },
      juicio: { say: [["nim", "¿En el Juicio? ¿Una nana? Se van a reír."],
                      [null, "Pero se saca las manos de los bolsillos."],
                      ["nim", "Está bien. No voy a declarar a favor de nadie. Voy a cantar lo que pasó en el Barrio. Y si los nueve pueblos tienen que estar en el Corazón, el Barrio va a estar. Alguien tiene que acordarse de los que no pagaron por ver."]], end: { xp: 18, flag: ["e3_nimCanta", "u3_barrio"] } },
      escuchar: { say: [[null, "Nim canta la nana entera. Es la misma que cantaba de niño en la verja, pero más grave, más lenta."],
                        [null, "Tu criatura se acerca y se sienta a sus pies. No la conoce. Pero se sabe la nana, como si se la hubieran cantado antes de nacer."]], end: { xp: 10, heal: 0.2 } },
    } },
  });

  /* ---------- Lago Espejo: beber la visión, Remanso y las ruinas de la Cantora ---------- */
  add("lake", {
    "e3-beber": { kind: "dialogo", need: { era: 3, layer: 1 }, first: true, who: { ola: "Ola", orilla: "Orilla" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla del Lago Espejo hay barcas, cuerdas y cubos, y una fila de gente de todos los pueblos esperando su turno. Una mujer con collar de conchas reparte copas. Es Ola, ahora Madre de las Mareas."],
                 ["ola", "Cuidador. Llegas a tiempo. Tú estuviste en la Calma. Si bebes, vas a ver lo que sintió la Raíz esa noche. Lo que tú viviste desde afuera, ahora desde adentro."],
                 [null, "A su lado, una anciana con los ojos blancos, casi ciega, te toma la muñeca. Es Orilla, su hermana."],
                 ["orilla", "No bebas. Cada copa es un recuerdo que se le saca. Una Raíz que olvida lo que le prometieron se despierta. Yo lo vi en el agua antes de quedarme sin ojos."]],
           opts: [{ t: "«¿Cómo saben que el agua muestra lo que siente la Raíz?»", go: "como", once: true },
                  { t: "«Ola, ¿cuánta agua sacan por día?»", go: "cuanta", once: true },
                  { t: "Beber la visión de la Velada Negra", go: "beber" },
                  { t: "Negarte a beber", go: "negar" },
                  { t: "«Que beba otro y me lo cuente.»", go: "otro" }] },
      como: { say: [["ola", "Porque no muestra caras de cerca, ni palabras, ni nombres. Muestra frío, miedo, sed. Lo que siente algo muy grande que mira desde abajo."],
                    ["orilla", "Y porque cada vez que alguien bebe, en el fondo se apaga una luz chiquita. Yo las veía apagarse, una por una. Antes de quedarme ciega, había miles. Ahora, quién sabe."]], back: "a" },
      cuanta: { say: [["ola", "Treinta barriles. Cuarenta, en semana de juicio. Mi pueblo vagó cien años. Ahora tiene casas en la orilla. No me pidas que les quite las casas."],
                      ["orilla", "Nadie te pide eso, hermana. Te pido que no le quites la memoria a algo que solo tiene eso."]], back: "a" },
      beber: { say: [[null, "Bebes. El agua está fría y sabe a hierro."],
                     [null, "Estás abajo. Muy abajo. Arriba hay una plaza blanca, tan blanca que quema. Mil faroles te chupan a la vez, como mil bocas. No duele. Da sed. Una sed que crece hasta que ya no sabes qué te prometieron."],
                     [null, "Y en medio de la sed, una voz chiquita que viene de arriba y canta una nana que no sirve. Te das cuenta de que es la tuya."],
                     [null, "Vuelves en ti en la orilla. Orilla te sostiene la cabeza. Ola te mira con una copa vacía en la mano."],
                     ["orilla", "Ya lo sabes. Ahora no lo crees: lo sabes. Eso pesa distinto."]], end: { xp: 20, hurt: 0.1, flag: "m3_bebiste" } },
      negar: { say: [[null, "Devuelves la copa. Ola la toma sin enojo y se la da al siguiente de la fila."],
                     ["ola", "Respeto eso. Pero vas a declarar con lo que crees, no con lo que sabes. En el Juicio eso vale menos."],
                     ["orilla", "Vale lo mismo. Vale más, porque no le quitaste nada a nadie para tenerlo."]], end: { xp: 14, flag: "m3_noBebiste" } },
      otro: { say: [["ola", "¿Otro? Tengo al mejor. Remanso. Un niño de mi pueblo. Ve más que nadie y más rápido."],
                    [null, "Un niño flaco de unos diez años bebe la copa por ti. Se le ponen los ojos blancos un momento. Después te cuenta lo que vio, con la voz muy tranquila: la plaza blanca, la sed, una nana que no servía."],
                    ["orilla", "Ese niño bebe por todos. Algún día no va a volver de una visión, y todos los que bebieron a través de él van a decir que no sabían."]], end: { xp: 12, flag: ["m3_otroBebe", "e3_remansoBebe"] } },
    } },

    "e3-remanso": { kind: "encuentro", need: { era: 3, layer: 2 }, who: { remanso: "Remanso", ola: "Ola" }, start: "a", nodes: {
      a: { say: [[null, "Al atardecer, en el muelle, un niño de las Mareas está sentado con los pies en el agua y una copa en las manos. Tiene los labios grises y las pupilas muy grandes."],
                 ["remanso", "Hoy bebí doce. Para jueces, para Casas, para uno de la Corte. Me pagan con pescado. Mi mamá dice que es un don."],
                 ["remanso", "Yo quiero ver a mi papá. Murió en la Velada Negra, en la plaza, bailando. Nunca lo conocí. Dicen que en la copa número cien de esa noche se le ve la cara. Voy por la setenta y tres."]],
           opts: [{ t: "«¿Por qué la cien?»", go: "cien", once: true },
                  { t: "Llevártelo lejos del lago, al Vado", go: "lejos" },
                  { t: "Dejarlo ver", go: "ver" },
                  { t: "Pagarle para que vea por ti lo que necesitas para el Juicio", go: "pagar", fx: { cost: 20 } },
                  { t: "Hablar con Ola", go: "ola" }] },
      cien: { say: [["remanso", "Porque cada copa de la misma noche muestra un pedazo distinto. Como si la Raíz se acordara de a poco. Mi papá estaba en el borde de la plaza. Los bordes salen al final."],
                    [null, "Lo dice como un niño explica un juego. Le tiembla la copa en las manos."]], back: "a" },
      ola: { say: [["ola", "Es el mejor que tenemos. Gracias a él, las Mareas tienen casas. No me mires así: yo también bebí de chica, y aquí estoy."],
                   ["ola", "Aunque es verdad que me olvido de cosas. De la cara de Fogarín de joven, por ejemplo. Antes la tenía clarita."]], back: "a" },
      lejos: { say: [["ola", "¿Al Vado? ¿Sin el lago? Se va a secar como un pez."],
                     [null, "Pero Remanso ya se levantó. Te da la mano, mojada, fría."],
                     ["remanso", "En el Vado hay criaturas, ¿no? ¿Me dejan cuidar una? Una que no sepa nada de ninguna noche."],
                     [null, "Ola lo mira irse contigo. No lo detiene. Al llegar al Vado, Remanso duerme dos días seguidos. Al tercero pide pan, no agua."]], end: { xp: 18, flag: "m3_remansoLejos" } },
      ver: { say: [[null, "Te sientas a su lado. Remanso bebe la setenta y cuatro, la setenta y cinco. En la ochenta se ríe solo."],
                   ["remanso", "Lo vi. Bailaba mal. Pisaba a todo el mundo. Tenía una cinta gris en la muñeca."],
                   [null, "Sigue bebiendo. Ya no busca a su padre. Bebe por costumbre, mirando el agua con una sonrisa que da miedo."]], end: { xp: 12, flag: "m3_remansoVe" } },
      pagar: { say: [[null, "Le das las monedas y le pides lo que necesitas: la cara de la matriarca cuando vio el suelo negro. Remanso bebe sin preguntar."],
                     ["remanso", "Lloraba. Sabía. Sabía desde antes. Lo dejó pasar porque el Barrio tenía luz por primera vez."],
                     [null, "Te lo dice con la voz de alguien mucho más viejo. Después se queda mirando el agua, como si no se acordara de por qué está ahí."]], end: { xp: 14, flag: ["m3_remansoPagado", "e3_visionDestello"] } },
    } },

    "e3-ruinas": { kind: "encuentro", need: { era: 3, layer: 3 }, who: { orilla: "Orilla" }, start: "a", nodes: {
      a: { say: [[null, "El lago bajó tanto que en la orilla norte asoman muros de piedra tallada. Calles, escalones, una plaza redonda. Un pueblo entero, debajo del agua, desde hace siglos."],
                 ["orilla", "Llévame. No veo, pero lo siento en los pies. Estas piedras cantan, igual que las del Corazón."],
                 [null, "En el centro de la plaza hundida hay un pedestal vacío. Grabadas en la base, letras antiguas: «Aquí vivía el pueblo que vio. Una de nosotras se quedó para que el lago siguiera viendo»."]],
           opts: [{ t: "Leerle a Orilla lo que dice la base", go: "leer", once: true },
                  { t: "Mostrar las ruinas a todo el Claro", go: "mostrar" },
                  { t: "Taparlas otra vez con piedras y barro", go: "tapar" },
                  { t: "Vendérselas a los mercaderes de los Altos", go: "vender" }] },
      leer: { say: [[null, "Le lees las letras en voz alta. Orilla pone las dos manos en la piedra."],
                    ["orilla", "La Cantora era de aquí. De las Mareas, antes de que fuéramos Mareas. Antes de que vagáramos. Se quedó en el Corazón para que el lago viera, y su pueblo se olvidó de ella."],
                    ["orilla", "Si el Claro sabe esto, el Juicio cambia. Las Mareas no son las que venden la memoria. Son las que la pagaron primero."]], fx: { flag: "e3_ruinasLeidas" }, back: "a" },
      mostrar: { say: [[null, "Traes a jueces, a gente de las Casas, de la Corte, del Bosque. Caminan por las calles hundidas con el barro hasta los tobillos."],
                       [null, "Nadie dice nada mucho tiempo. Después, una mujer de las Casas pregunta en voz alta lo que todos piensan: «¿Y si cada pueblo pagó alguna vez, y todos lo olvidamos?»."],
                       ["orilla", "Ya está. Ya no se puede tapar. Que lo sepa también la generación que viene, aunque le duela."]], end: { xp: 22, flag: "m3_ruinasVistas" } },
      tapar: { say: [["orilla", "¿Taparlas? ¿Por qué?"],
                     [null, "Le explicas: si se sabe que la Cantora era de las Mareas, todos los pueblos van a querer reclamar su propia estatua, su propio pago, su propio juicio."],
                     [null, "Orilla lo piensa con las manos en la piedra. Al final ayuda a echar barro sobre las letras, despacio, como se tapa a un niño dormido."],
                     ["orilla", "Hay cosas que se guardan para cuando el Claro esté listo. Espero que alguien se acuerde de dónde las dejamos."]], end: { xp: 14, flag: "m3_ruinasTapadas" } },
      vender: { say: [[null, "Llamas a Trueque. En dos días hay un puesto con toldo a rayas en la plaza hundida. Se cobra la entrada. Se venden piedritas talladas como recuerdo."],
                      ["orilla", "Las Mareas comen. Lo sé. Mi hermana dirá que hiciste bien."],
                      [null, "No dice si ella también lo cree. Esa noche se queda sola en la plaza hundida, con las manos en el pedestal vacío, hasta que sube el agua."]], end: { xp: 10, coins: 40, flag: "m3_ruinasVendidas" } },
    } },

    "e3-ola": { kind: "dialogo", need: { era: 3, layer: 2 }, who: { ola: "Ola" }, start: "a", nodes: {
      a: { say: [[null, "De noche, en la barca grande de las Mareas, Ola cuenta los barriles de la semana. Tiene un cuaderno lleno de números y las manos llenas de nudos."],
                 ["ola", "Las Casas me ofrecieron un trato. Si las Mareas declaran a su favor, nos dan la orilla norte para siempre, con papeles. Nunca tuvimos papeles."],
                 ["ola", "La Corte me ofreció otro: si declaramos a su favor, nos enseñan a sacar el agua sin que se note. Nunca tuvimos secretos."]],
           opts: [{ t: "«¿Y qué quiere usted, Ola?»", go: "quiere", once: true },
                  { t: "«Fogarín guarda una copa de cada diez.»", go: "fogarin", cNeed: "e3_copaGuardada" },
                  { t: "«Saque la mitad. Que el lago reponga.»", go: "mitad" },
                  { t: "«Acepte el trato de las Casas.»", go: "casas" }] },
      quiere: { say: [["ola", "Que mi pueblo deje de vagar. Eso es todo. Me da igual cómo. Mi abuela murió en una barca. Mi madre también. Yo quiero morirme en una casa."],
                      ["ola", "Y mi hermana quiere que deje de sacar agua. Las dos tenemos razón. Eso es lo peor."]], back: "a" },
      fogarin: { say: [["ola", "¿Una de cada diez? ¿Ese tonto hizo eso?"],
                       [null, "Se ríe con los ojos húmedos."],
                       ["ola", "Entonces las Mareas también. Un barril de cada diez vuelve al fondo. Sin vender. Y si los pueblos van al Corazón, las Mareas van con el barril que devolvimos. Que se vea que alguien empezó a pagar."]], end: { xp: 20, flag: ["e3_barrilDevuelto", "u3_agua"] } },
      mitad: { say: [["ola", "¿La mitad? La mitad de las casas, entonces. La mitad de los niños que dejan de vagar."],
                     [null, "Cierra el cuaderno. Lo vuelve a abrir. Tacha un número y escribe otro."],
                     ["ola", "Veinte barriles. No quince. Veinte. Y si mi hermana pregunta, dile que fue idea tuya. Así me odia a ti y no a mí."]], end: { xp: 16, flag: ["e3_menosAgua", "u3_agua"] } },
      casas: { say: [["ola", "Papeles. La orilla norte. Para siempre."],
                     [null, "Ola firma esa misma noche, a la luz de un farol de las Casas. Al terminar, se queda mirando la firma mucho rato."],
                     ["ola", "Mi madre no sabía escribir su nombre. Yo acabo de vender el de mi pueblo por un pedazo de orilla. Supongo que eso es progresar."]], end: { xp: 10, coins: 30, flag: "e3_olaCasas" } },
    } },
  });

  /* ---------- Cuevas del Eco: Cuarzo graba lo que se ve ---------- */
  add("caves", {
    "e3-cuarzo": { kind: "encuentro", need: { era: 3, layer: 1 }, who: { cuarzo: "Cuarzo, cronista" }, start: "a", nodes: {
      a: { say: [[null, "La Sala del Eco ya no está en silencio. Hay cincel, martillo y polvo por todas partes. Un hombre de la Hondura, con los brazos blancos de piedra molida, graba en la pared una escena: una plaza llena de faroles."],
                 ["cuarzo", "La gente viene, bebe, me cuenta lo que vio, y yo lo grabo. El agua se olvida. La piedra no. Cuando la última copa se seque, esto va a seguir aquí."],
                 ["cuarzo", "Me llamo Cuarzo. Mi abuelo era Basalto. Él golpeaba las paredes para que nadie durmiera. Yo las escribo para que nadie se olvide."]],
           opts: [{ t: "Mirar la pared grabada", go: "mirar", once: true },
                  { t: "Contarle lo que viviste en la Calma, para que lo grabe", go: "contar" },
                  { t: "«Si graba todo, va a grabar también lo que duele.»", go: "duele" },
                  { t: "«Grabe también lo que se contradice.»", go: "contradice", cNeed: "e3_copasCuevas" }] },
      mirar: { say: [[null, "La pared es enorme. Hay cien noches grabadas, una al lado de otra. La Velada aparece doce veces. En cada una, la matriarca tiene una cara distinta: triste, alegre, asustada, de espaldas."],
                     ["cuarzo", "Cada uno ve lo que lleva adentro. Yo grabo lo que me cuentan. La piedra no elige."]], back: "a" },
      contar: { say: [[null, "Le cuentas la Calma: la Ley del Regreso, las cintas grises, los Pozos Ciegos, las cuatro estatuas, lo que decidiste al final. Cuarzo graba sin parar hasta la madrugada."],
                      ["cuarzo", "Esta es distinta. No es una visión. Es alguien que estuvo y se acuerda con sus propios ojos. Eso no lo tiene ninguna copa."],
                      ["cuarzo", "La Hondura va a ir al Corazón con esta pared en la memoria. Que nadie diga que no había un testigo de carne y hueso."]], end: { xp: 20, flag: ["e3_testigoGrabado", "u3_piedra"] } },
      duele: { say: [["cuarzo", "Claro que lo voy a grabar. Para eso estoy."],
                     [null, "Te señala un rincón de la pared, más oscuro. Ahí grabó algo que nadie quiso ver: niños del Barrio durmiendo en la calle la noche de la Velada, mientras arriba bailaban."],
                     ["cuarzo", "Esto nadie lo pidió. Lo trajo un viejo que bebió por error. Si la piedra no lo guarda, nadie lo guarda."]], end: { xp: 12, flag: "e3_grabadoDuele" } },
      contradice: { say: [[null, "Le cuentas lo de las copas de Ampolla, que cambian de final cada día. Cuarzo deja el cincel."],
                          ["cuarzo", "¿Dos noches que no coinciden? Entonces la Raíz no se acuerda bien. Entonces ninguna visión es prueba."],
                          [null, "Graba las dos versiones de la misma copa, una al lado de la otra, con una raya en medio. Debajo escribe: «La misma noche. La misma agua. Dos recuerdos»."],
                          ["cuarzo", "Esto lo va a ver el Juicio. La Hondura irá al Corazón con esta pared, y no a favor de nadie."]], end: { xp: 22, flag: ["e3_dosNoches", "u3_piedra"] } },
    } },

    "e3-grabado": { kind: "dialogo", need: { era: 3, layer: 2 }, who: { cuarzo: "Cuarzo, cronista" }, start: "a", nodes: {
      a: { say: [[null, "Cuarzo te espera en la boca de la cueva con el cincel en la mano y cara de no haber dormido."],
                 ["cuarzo", "Grabé algo que no debí. Vino una señora de las Casas, bebió, y me contó lo que vio. Lo grabé sin pensar. Ahora hay gente haciendo fila para verlo."],
                 [null, "En la pared, recién grabada: un hombre de las Casas que empuja a un niño del Barrio a un pozo abierto, la noche de la Velada, para que deje de mirar."]],
           opts: [{ t: "«¿Quién es el hombre?»", go: "quien", once: true },
                  { t: "Borrar el grabado", go: "borrar" },
                  { t: "Dejarlo a la vista", go: "dejar" },
                  { t: "Taparlo con una tela, para quien quiera verlo", go: "tela" }] },
      quien: { say: [["cuarzo", "No se ve la cara. La Raíz no ve caras de cerca. Pero tiene el abrigo de una Casa, y la Casa se reconoce por el bordado."],
                     ["cuarzo", "Los nietos de ese hombre viven en el Prado. Desde ayer, nadie les vende pan."]], back: "a" },
      borrar: { say: [[null, "Cuarzo levanta el martillo, duda, y lo baja. Golpea hasta que la escena es solo piedra rota."],
                      ["cuarzo", "Mi abuelo decía que la Sala existe para que los nombres no se pierdan. Acabo de perder uno a propósito."],
                      [null, "Al día siguiente, la señora de las Casas vuelve a beber la misma visión y la cuenta en la plaza. Ya no hace falta la piedra."]], end: { xp: 10, flag: "e3_grabadoBorrado" } },
      dejar: { say: [["cuarzo", "Lo dejo. La piedra no elige."],
                     [null, "La fila crece. Esa noche alguien rompe la ventana de una casa del Prado con una piedra de las Cuevas."]], end: { xp: 8, flag: "e3_grabadoVisto" } },
      tela: { say: [[null, "Cuelgan una tela gris delante del grabado. Al lado, Cuarzo escribe con tiza: «Lo que hay detrás lo vio la Raíz. No dice quién era. Mire solo si va a recordar las dos cosas»."],
                    ["cuarzo", "Algunos levantan la tela. La mayoría no. Los que la levantan salen callados."]], end: { xp: 14, flag: "e3_grabadoTela" } },
    } },
  });

  /* ---------- El Fondo Blanco: sueños robados ---------- */
  add("deep", {
    "e3-nevisca": { kind: "dialogo", need: { era: 3, layer: 1 }, who: { nevisca: "Nevisca, soñadora del Turno" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Turno, una anciana con las manos cubiertas de cicatrices de escarcha recibe a los soñadores que llegan llorando. Tiene los labios agrietados desde hace una generación."],
                 ["nevisca", "Vienen de noche. Se despiertan y les falta algo. Un recuerdo chiquito: la cara de un perro, una canción de cuna, el olor de una sopa. Un hueco donde antes había algo."],
                 ["nevisca", "Las Mareas dicen que el agua muestra lo que la Raíz recuerda. Nosotros decimos que lo que muestra lo sacó de nuestros sueños. Cada copa que se bebe allá es un sueño que se nos roba aquí."]],
           opts: [{ t: "«¿Cómo saben que es lo mismo?»", go: "como", once: true },
                  { t: "«Usted le contestó a la Raíz una vez, con el verso de Cira.»", go: "verso", cNeed: "e2_oyenPromesa" },
                  { t: "Soñar en el Turno esta noche", go: "sonar" },
                  { t: "«Vayan al Juicio y cuéntenlo.»", go: "juicio" }] },
      como: { say: [["nevisca", "Porque un soñador se despertó sin la cara de su madre. A la semana, un juez del Prado declaró con una visión: una mujer del Fondo cantándole a su hijo. Era ella. La madre del soñador."],
                    ["nevisca", "La Raíz no tiene memoria propia, Cuidador. Tiene la nuestra. Todo lo que soñamos sobre ella, se lo quedó."]], back: "a" },
      verso: { say: [["nevisca", "Le dije que lo que tomamos lo íbamos a devolver. Dejó de pedir. Durante veinte años, durmió tranquilo."],
                     ["nevisca", "Ahora le están sacando la memoria a cubos. Se va a olvidar de la promesa. Y cuando se olvide, va a volver a pedir. Y ya no va a ser agua lo que pida."],
                     ["nevisca", "Si el Corazón llama, el Fondo Blanco va a ir. A recordarle el verso. Alguien tiene que acordarse por él."]], end: { xp: 20, flag: ["e3_versoRecuerda", "u3_escarcha"] } },
      sonar: { say: [[null, "Te acuestas en el círculo con los soñadores. Sueñas tu primera noche en el Vado: el huevo, la luz, el primer llanto de tu primera criatura."],
                     [null, "Te despiertas. Sabes que soñaste algo hermoso. No sabes qué. Hay un hueco tibio donde estaba."],
                     ["nevisca", "¿Ves? Ahora alguien en el Lago va a beber tu primera noche. Ojalá le haga bien."]], end: { xp: 12, hurt: 0.05, flag: "e3_suenoRobado" } },
      juicio: { say: [["nevisca", "¿Al Juicio? ¿A decir que las pruebas de todos están hechas con nuestros sueños? Nos van a odiar todos los pueblos a la vez."],
                      [null, "Lo piensa. Se pasa la lengua por los labios partidos."],
                      ["nevisca", "Está bien. Que nos odien juntos. Por lo menos así están de acuerdo en algo. Y el Fondo Blanco irá al Corazón cuando llamen."]], end: { xp: 16, flag: ["e3_suenosJuicio", "u3_escarcha"] } },
    } },

    "e3-huecos": { kind: "encuentro", need: { era: 3, layer: 2 }, who: { nieve: "Nieve" }, start: "a", nodes: {
      a: { say: [[null, "En la laguna helada, una mujer patina sola, en círculos, con la mirada perdida. Lleva en el cuello una pluma azul descolorida."],
                 ["nieve", "Te conozco. Eras quien patinaba mal. Me acuerdo de eso. No me acuerdo de mi hermano."],
                 ["nieve", "Granizo. Así se llamaba. Lo sé porque está escrito en la puerta de casa. Pero no tengo su cara. Una mañana me desperté y ya no estaba. Dicen que alguien en el Prado bebió una visión de dos niños patinando."]],
           opts: [{ t: "«¿Qué le pasó a Granizo?»", go: "granizo", once: true },
                  { t: "Contarle cómo era su hermano", go: "contar" },
                  { t: "«Busquemos la copa donde está su recuerdo.»", go: "copa" },
                  { t: "Patinar con ella", go: "patinar" }] },
      granizo: { say: [["nieve", "Se cayó al lago de abajo. El invierno de la Calma, cuando el hielo se puso blando. Por eso la Raíz lo tenía: lo vio caer."],
                       [null, "Lo dice sin llorar. No puede llorar por alguien de quien no se acuerda."]], back: "a" },
      contar: { say: [[null, "Le cuentas: un niño con la nariz roja que inventaba cosas, que decía que el rey se estaba estirando, que se reía cuando te caías."],
                      [null, "Nieve escucha con los ojos cerrados. No vuelve el recuerdo. Pero sonríe con la parte de la cara que se acuerda sola."],
                      ["nieve", "Inventaba cosas. Sí. Eso suena a hermano. Gracias. Ahora tengo algo prestado donde antes no había nada."]], end: { xp: 16, heal: 0.15, flag: "e3_granizoContado" } },
      copa: { say: [[null, "Preguntan en el Prado. La copa existe. La tiene un juez de la Luz, que la usa para probar que el hielo del Fondo se rompió por culpa de la Corte."],
                    ["nieve", "¿Mi hermano es una prueba? ¿En un juicio de otros?"],
                    [null, "El juez no la devuelve. Dice que es evidencia. Nieve vuelve a la laguna y patina hasta que oscurece."]], end: { xp: 10, flag: "e3_copaGranizo" } },
      patinar: { say: [[null, "Patinas con ella. Te caes. Ella se ríe. Por un instante, la risa le sale igual a la de antes."],
                       ["nieve", "Eso. Eso me acuerdo. Alguien que se reía cuando te caías. No sé quién. Pero me acuerdo de la risa."]], end: { xp: 10 } },
    } },
  });

  /* ---------- Corazón del Claro: la Cantora al aire y el final de la era ---------- */
  add("heart", {
    "e3-cantora": { kind: "encuentro", need: { era: 3, layer: 4 }, who: { brezo: "Brezo, guarda del Tocón" }, start: "a", nodes: {
      a: { say: [[null, "El suelo del Corazón se hundió otra vez. La cuarta estatua quedó al aire entera, de pies a cabeza. Es una mujer con la boca abierta y la cara vuelta hacia el oeste, hacia el lago."],
                 ["brezo", "Cuarenta años cuidando el Tocón y nunca supe hacia dónde miraba. Ahora lo sé. Miraba su casa."],
                 [null, "Brezo es muy viejo. Se apoya en un bastón. Alrededor de la estatua, gente de todos los pueblos deja copas vacías, como ofrenda."]],
           opts: [{ t: "«¿Por qué dejan copas?»", go: "copas", once: true },
                  { t: "«Su pueblo estaba bajo el lago. Lo vi.»", go: "pueblo", cNeed: "e3_ruinasLeidas" },
                  { t: "Limpiar la cara de la estatua", go: "limpiar" },
                  { t: "Recoger las copas y llevarlas al lago", go: "llevar" }] },
      copas: { say: [["brezo", "Porque creen que la Cantora era la primera que bebió. Que ella empezó todo. Le traen las copas para que cargue con ellas."],
                     ["brezo", "Es lo que hacemos siempre: buscar a alguien de piedra para que cargue con lo que hicimos nosotros."]], back: "a" },
      pueblo: { say: [[null, "Le cuentas lo de las ruinas, el pedestal vacío, las letras. Brezo pone la mano en el pie de la estatua."],
                      ["brezo", "Entonces no fue la primera que bebió. Fue la primera que pagó. Y las copas que le dejan son lo contrario de lo que merece."]], back: "a" },
      limpiar: { say: [[null, "Limpias el barro de la cara de la estatua. Debajo, la piedra está gastada en dos líneas, desde los ojos hasta la barbilla. Como si hubiera llorado agua durante siglos."],
                       ["brezo", "Lloraba hacia el lago. Todos estos años. Y nosotros creíamos que cantaba."]], end: { xp: 16, flag: "e3_cantoraLlora" } },
      llevar: { say: [[null, "Juntas las copas vacías en un saco. Son cientos. Las llevas al Lago Espejo y las hundes una por una en la orilla norte, donde está la plaza hundida."],
                      [null, "Al hundir la última, el agua se aclara un momento y refleja el Corazón entero, con la estatua mirando hacia ti."],
                      ["brezo", "Le devolviste algo. Poco. Pero es la primera vez que alguien le devuelve algo en lugar de pedirle."]], end: { xp: 20, flag: "e3_copasDevueltas" } },
    } },

    "e3-final": { kind: "dialogo", need: { era: 3, eraWin: "heart" }, first: true, once: true, who: { albura: "Jueza Albura", ola: "Ola", nim: "Nim" }, start: "a", nodes: {
      a: { say: [[null, "La Raíz que Olvida no se levanta enojada. Se levanta confundida, buscando algo, como quien entra a un cuarto y no se acuerda a qué entró. El Tocón tiembla en olas lentas."],
                 [null, "Arriba, junto a la estatua de la Cantora, esperan la jueza del Juicio, Ola con su collar de conchas y Nim con las manos en los bolsillos. La jueza trae dos rollos de papel."],
                 ["albura", "La Crónica Oficial. Dos versiones. Una culpa a la Corte y a la matriarca Destello. La otra culpa a las Casas. El Claro necesita una. Firme usted, Cuidador. Es la única firma que todos van a respetar."],
                 ["ola", "Y abajo, el lago se queda sin memoria. Si seguimos sacando agua para probar quién tuvo la culpa, la Raíz se va a olvidar de por qué duerme."]],
           opts: [{ t: "«¿Qué pasa si firmo la del Farol?»", go: "q1", once: true },
                  { t: "«¿Y si firmo la de las Mareas?»", go: "q2", once: true },
                  { t: "«¿Y si no hay versión que firmar?»", go: "q3", once: true },
                  { t: "Firmar la versión del Farol", go: "farol" },
                  { t: "Firmar la versión de las Mareas", go: "mareas" },
                  { t: "Romper el espejo del lago, con los nueve pueblos de testigos", go: "espejo", cNeed: "e3_nueve" }] },
      q1: { say: [["albura", "El Día queda unido. Las Casas cierran la herida. La Corte paga, aunque solo tuvo la mitad de la culpa. Y no lo va a olvidar."],
                  ["nim", "La Corte guarda rencores mejor que nadie. Se los pasa de madre a hija con el velo."]], back: "a" },
      q2: { say: [["albura", "Las Casas pagan reparaciones. No tienen dinero, así que venden lo que tienen: sus forjas, sus talleres, sus faroles."],
                  ["ola", "Y el Gremio de la Brasa los compra baratos. Fogarín ya me lo dijo. No lo quiere, pero el Gremio sí."]], back: "a" },
      q3: { say: [["ola", "Rompemos el espejo. El agua del lago deja de mostrar nada, nunca más. Ni la Velada, ni la Calma, ni la Cantora."],
                  ["nim", "Nadie puede probar nada. Ni culpar, ni defenderse. En una generación nadie se acuerda de la Línea, ni de la condición, ni de nada."],
                  ["albura", "Y sin juicio no hay culpable, y sin culpable la herida queda abierta. Eso solo lo aceptan los pueblos si todos lo aceptan a la vez. Si falta uno, ese uno va a decir que le robaron la prueba."]], back: "a" },
      farol: { say: [[null, "Firmas la Crónica Oficial. La jueza la sella. En el Prado suenan las campanas de las Casas. Al fondo, los de la Corte se bajan el velo todos a la vez."],
                     ["albura", "Se cerró la herida. Ahora hay que esperar a ver qué cicatriz deja."],
                     ["nim", "Una Sombra resentida es una Sombra paciente. Acuérdate de esto cuando vuelva."]], end: { xp: 60, flag: "m3_farol" } },
      mareas: { say: [[null, "Firmas la versión de las Mareas. Las Casas aceptan en silencio. Esa misma semana empiezan a vender: una forja, un taller, la Torre del Alba entera."],
                      ["ola", "Las Mareas tienen papeles. Las Casas tienen deudas. El Gremio tiene todo lo demás. No sé si ganamos."],
                      [null, "En el Cráter, alguien prende un horno que antes era de las Casas. Hace calor por primera vez en mucho tiempo."]], end: { xp: 60, flag: "m3_mareas" } },
      espejo: { say: [[null, "Llegan los nueve. Cada uno trae algo: la lista de Noctua, el cuaderno de hule, la pared de dos noches, el barril devuelto, la nana del Barrio, la canción que olvida, el frasco entero de los Altos, el verso del Fondo, la copa que el Gremio no vendió."],
                      [null, "Bajas al lago con Ola y con Orilla. Orilla pone las manos en el agua. Ola levanta una piedra de la plaza hundida y la deja caer en el centro."],
                      [null, "El espejo se rompe sin ruido. El agua se pone gris, quieta, ciega. En el Corazón, la Raíz deja de buscar. Se queda quieta, como alguien que decide no acordarse."],
                      ["albura", "No hay veredicto. No hay culpable. No hay prueba. Que la generación que viene nos perdone por no dejarle nada que probar."],
                      ["nim", "O que nos odie. Por lo menos nos va a odiar a todos juntos."]], end: { xp: 60, flag: "m3_espejo" } },
    } },
  });
})(window.EVEVENTS);
